#ifndef UBE_SEMANTIC_OWNER_OBSERVATION_H
#define UBE_SEMANTIC_OWNER_OBSERVATION_H
extern int32_t shared_is_live(void*);
struct document {void* bytes;int32_t content,scalars,lines;};
struct source_owner {struct document document;int32_t source;};
struct envelope {int32_t format,kind,first,last;uint8_t identity;};
struct association {void* input;struct envelope envelope;int32_t source,package,module,first,count,private_module;void* name_map;};
struct syntax_failure {int32_t kind,first,last;};
struct syntax_metrics {int32_t tokens,transitions,names,pending,depth;};
struct source_work {void* owner;void* tokens;void* syntax;struct syntax_failure failure;struct syntax_metrics metrics;int64_t worker;int32_t state,max_tokens,max_nodes,max_pending,max_depth;};
struct syntax_result {void* nodes;int32_t count,root,source;};
struct syntax_node {int32_t kind,first,last,child,next,count;};
struct project_syntax {void* project;void* work;};
static int original_graph(struct catalog* c){CHECK(c&&shared_is_live(c)&&c->input&&shared_is_live(c->input)&&c->sources&&shared_is_live(c->sources));struct project_syntax* project=c->input;CHECK(project->work&&shared_is_live(project->work)&&ube_value_array_length(&project->work)==c->source_count);int module_facts=0;for(int32_t i=0;i<c->source_count;++i){struct association* s=*(void**)ube_array_element(c->sources,i);CHECK(s&&shared_is_live(s)&&s->input&&shared_is_live(s->input)&&s->source==i&&s->module==i);struct source_work* w=s->input;CHECK(*(void**)ube_array_element(project->work,i)==w&&w->owner&&shared_is_live(w->owner)&&w->tokens&&shared_is_live(w->tokens)&&w->syntax&&shared_is_live(w->syntax)&&w->state==1);struct source_owner* o=w->owner;CHECK(o->source==i&&o->document.bytes&&shared_is_live(o->document.bytes)&&o->document.content==0);const char* expected=i?reference:detailed;size_t length=strlen(expected),lines=1;for(size_t at=0;at<length;++at){CHECK(*(uint8_t*)ube_array_element(o->document.bytes,(int32_t)at)==(uint8_t)expected[at]);if(expected[at]=='\n')++lines;}CHECK(ube_value_array_length(&o->document.bytes)==(int32_t)length&&o->document.scalars==(int32_t)length&&o->document.lines==(int32_t)lines);CHECK(ube_value_array_length(&w->syntax)==1);struct syntax_result* syntax=ube_array_element(w->syntax,0);CHECK(syntax->nodes&&shared_is_live(syntax->nodes)&&syntax->source==i&&syntax->count==ube_value_array_length(&syntax->nodes)&&s->name_map&&shared_is_live(s->name_map)&&ube_value_array_length(&s->name_map)==syntax->count);for(int32_t node_id=0;node_id<syntax->count;++node_id){struct syntax_node* node=ube_array_element(syntax->nodes,node_id);int32_t mapped=*(int32_t*)ube_array_element(s->name_map,node_id);if(node->kind==1){CHECK(mapped>0&&mapped<=c->name_count);struct name* n=name(c,mapped-1);CHECK(n->source==i&&n->syntax==node_id&&n->first==node->first);}else CHECK(mapped==0);}struct syntax_node* root_node=ube_array_element(syntax->nodes,syntax->root);CHECK(root_node&&root_node->kind==45&&root_node->child>=0);struct syntax_node* header=ube_array_element(syntax->nodes,root_node->child);CHECK(header&&header->kind==50&&s->envelope.format==1&&s->envelope.kind==1&&s->envelope.identity);const char* quoted=i?"\"B\"":"\"A\"";const char* at=strstr(expected,quoted);CHECK(at&&s->envelope.first==(int32_t)(at-expected)&&s->envelope.last==s->envelope.first+3);struct name* module_name=name(c,decl(c,i)->name);CHECK(module_name->source==i&&module_name->syntax==-1&&module_name->first==s->envelope.first&&module_name->last==s->envelope.last&&module_name->byte_count==1&&*(uint8_t*)ube_array_element(c->name_bytes.bytes,module_name->byte_first)==(uint8_t)('a'+i));for(int32_t f=0;f<c->fact_count;++f){struct fact* fact=ube_array_element(c->facts,f);if(fact->kind==8&&fact->left==1&&fact->source==i){CHECK(fact->target==i&&fact->right==0&&fact->syntax==root_node->child&&fact->type==-1&&fact->auxiliary==-1&&fact->extra==-1);++module_facts;}}}CHECK(module_facts==c->source_count);return 0;}
static uint64_t owners_hash(struct catalog* c){if(original_graph(c))return 0;uint64_t h=hash_catalog(c);h=hash_bytes(h,&c->input,sizeof c->input);h=hash_bytes(h,&c->sources,sizeof c->sources);struct project_syntax* project=c->input;h=hash_bytes(h,&project->work,sizeof project->work);for(int32_t i=0;i<c->source_count;++i){struct association* s=*(void**)ube_array_element(c->sources,i);h=hash_bytes(h,&s,sizeof s);h=hash_bytes(h,&s->input,sizeof s->input);h=hash_bytes(h,&s->name_map,sizeof s->name_map);struct source_work* w=s->input;h=hash_bytes(h,&w->owner,sizeof w->owner);h=hash_bytes(h,&w->tokens,sizeof w->tokens);h=hash_bytes(h,&w->syntax,sizeof w->syntax);struct source_owner* o=w->owner;h=hash_bytes(h,&o->document.bytes,sizeof o->document.bytes);for(int32_t b=0;b<o->document.scalars;++b)h=hash_bytes(h,ube_array_element(o->document.bytes,b),1);for(int32_t t=0;t<ube_value_array_length(&w->tokens);++t)h=hash_bytes(h,ube_array_element(w->tokens,t),36);struct syntax_result* syntax=ube_array_element(w->syntax,0);for(int32_t n=0;n<syntax->count;++n){h=hash_bytes(h,ube_array_element(syntax->nodes,n),24);h=hash_bytes(h,ube_array_element(s->name_map,n),4);}}return h;}
#endif
